/// <summary>
/// Controller class for managing the Sales load planning report generation process.
/// </summary>
public class METSalesLoadPlanningController extends SrsReportRunController
{
    CreatedTransactionId        createdTransactionId;
    METOrderExtractScreenTmp    tempTable;

}

Method.Source:
/// <summary>
/// Entry point for the sales load planning report controller.
/// Initializes the controller, processes arguments, and handles cleanup if the dialog is cancelled.
/// </summary>
/// <param name="_args">Arguments containing report parameters and context.</param>
public static void main(Args _args)
{
    METSalesLoadPlanningController controller = new METSalesLoadPlanningController();
    METLoadPlanningReport loadPlanningReport = _args.parmEnum();
    controller.parmArgs(_args);
    controller.parmShowDialog(false);

    controller.initFromArgs(_args);
    controller.startOperation();

    if (controller.isDialogCancelled())
    {
        if (loadPlanningReport == METLoadPlanningReport::LoadPlanningAidReport)
        {
            METsalesOrderLoadPlanningAidLinesTmp salesOrderLoadPlanningAidLinesTmp;

            delete_from salesOrderLoadPlanningAidLinesTmp
                where salesOrderLoadPlanningAidLinesTmp.CreatedTransactionId == controller.createdTransactionId;
        }
        else
        {
            METsalesOrderLoadPlanningLinesTmp salesLoadPlanningdLinesTmp;

            delete_from salesLoadPlanningdLinesTmp
                where salesLoadPlanningdLinesTmp.CreatedTransactionId == controller.createdTransactionId;
        }
    }
}

/// <summary>
/// Indicates whether the report dialog was cancelled by the user.
/// </summary>
/// <returns>True if the dialog was cancelled; otherwise, false.</returns>
public boolean isDialogCancelled()
{
    return dialogCanceled;
}

/// <summary>
/// Creates the report data based on the provided arguments and selected records.
/// </summary>
/// <param name="_args">Arguments containing the selected records and report type.</param>
public void createReportData(Args _args)
{
    Map                     map = new Map(Types::Int64, Types::String);
    FormRun                 formRun;
    METLoadPlanningReport   loadPlanningReport = _args.parmEnum();

    Map                     metricsCacheMap;

    tempTable.linkPhysicalTableInstance(_args.record() as METOrderExtractScreenTmp);

    if (_args.caller())
    {
        formRun = _args.caller();
        FormDataSource dsExtractTmp = formRun.dataSource(formDataSourceStr(METOrderExtractScreen, METOrderExtractScreenTmpDS));
        dsExtractTmp.research(false);
        dsExtractTmp.reread();

        if (formHasMethod(formRun, formMethodStr(METOrderExtractScreen, getMetricsCacheMap)))
        {
            metricsCacheMap = formRun.getMetricsCacheMap();
        }

        METOrderExtractScreenTmp tmpRecord = dsExtractTmp.getFirst(false);
        while (tmpRecord)
        {
            if (tmpRecord.Selection) // Only process records with Selection = 1
            {
                // Example: key = SalesId, value = record buffer
                map.insert(tmpRecord.RecId, tmpRecord.SalesId);
            }

            tmpRecord = dsExtractTmp.getNext();
        }

        METOrderExtractScreenTmp tmpSelectedRecord = _args.record();

        if (!map.exists(tmpSelectedRecord.RecId) && tmpSelectedRecord.RecId && tmpSelectedRecord.Selection)
        {
            map.insert(tmpSelectedRecord.RecId, tmpSelectedRecord.SalesId);
        }

        if (loadPlanningReport == METLoadPlanningReport::LoadPlanningReport)
        {
            createdTransactionId = METLoadPlanningReportHelper::setSOReportLoadPlanningTmp(map, tempTable, metricsCacheMap);
        }
        else
        {
            createdTransactionId = METLoadPlanningReportHelper::setSOReportLoadPlanningAidTmp(map, tempTable, metricsCacheMap);
        }
    }
}

/// <summary>
/// Initializes the controller from the provided arguments and sets the report name.
/// </summary>
/// <param name="_args">Arguments containing the report type and context.</param>
public void initFromArgs(Args _args)
{
    METLoadPlanningReport loadPlanningReport = _args.parmEnum();

    switch (loadPlanningReport)
    {
        case METLoadPlanningReport::LoadPlanningAidReport:
            this.parmReportName(ssrsReportStr(METSalesLoadPlanningAidReport, Report));
            break;

        case METLoadPlanningReport::LoadPlanningReport:
            this.parmReportName(ssrsReportStr(METSalesLoadPlanningReport, Report));
            break;
    }

    this.createReportData(_args);
}

/// <summary>
/// Modifies the report contract before running the report, setting the transaction ID.
/// </summary>
protected void preRunModifyContract()
{
    METSalesLoadPlanningContract contract = this.parmReportContract().parmRdpContract() as METSalesLoadPlanningContract;

    new SRSReportRunPermission().assert();

    contract.parmTransaction(createdTransactionId);
}
